USE vmmon;
ALTER TABLE servers ADD COLUMN is_services TINYINT NOT NULL DEFAULT 0, ADD COLUMN maint_until DATETIME NULL;
ALTER TABLE alert_rules MODIFY metric ENUM('cpu','mem','disk','check','offline','net_err','net_drop','net_down','net_util') NOT NULL, ADD COLUMN server_id INT NULL, ADD COLUMN iface VARCHAR(255) NOT NULL DEFAULT '', ADD CONSTRAINT fk_rule_srv FOREIGN KEY (server_id) REFERENCES servers(id) ON DELETE CASCADE;
CREATE TABLE net_if(server_id INT NOT NULL, if_index INT NOT NULL, name VARCHAR(100), descr VARCHAR(255), alias VARCHAR(255), type INT DEFAULT 0, speed_mbps INT DEFAULT 0, mac VARCHAR(32), admin TINYINT DEFAULT 0, oper TINYINT DEFAULT 0, in_oct DOUBLE DEFAULT 0, out_oct DOUBLE DEFAULT 0, in_err DOUBLE DEFAULT 0, out_err DOUBLE DEFAULT 0, in_disc DOUBLE DEFAULT 0, out_disc DOUBLE DEFAULT 0, last_ts INT NULL, rate_in DOUBLE NULL, rate_out DOUBLE NULL, err_pm DOUBLE NULL, disc_pm DOUBLE NULL, PRIMARY KEY(server_id,if_index), FOREIGN KEY(server_id) REFERENCES servers(id) ON DELETE CASCADE);
CREATE TABLE net_hist(server_id INT NOT NULL, if_index INT NOT NULL, bk DATETIME NOT NULL, n INT DEFAULT 0, in_sum DOUBLE DEFAULT 0, in_max DOUBLE DEFAULT 0, out_sum DOUBLE DEFAULT 0, out_max DOUBLE DEFAULT 0, err_sum DOUBLE DEFAULT 0, err_max DOUBLE DEFAULT 0, disc_sum DOUBLE DEFAULT 0, disc_max DOUBLE DEFAULT 0, PRIMARY KEY(server_id,if_index,bk), FOREIGN KEY(server_id) REFERENCES servers(id) ON DELETE CASCADE);
